package com.academy.mudogroupware.auth;
import com.academy.mudogroupware.auth.application.result.TokenPair; import com.academy.mudogroupware.auth.application.service.TokenService; import com.academy.mudogroupware.auth.infrastructure.persistence.*; import com.academy.mudogroupware.global.infrastructure.security.jwt.*; import org.junit.jupiter.api.*; import java.util.Optional; import static org.assertj.core.api.Assertions.assertThat; import static org.mockito.Mockito.*;
class TokenServiceTest { @Test void replacesTokenForSameUser(){JwtProperties p=new JwtProperties();p.setSecret("test-secret-key-that-is-at-least-32-bytes-long");RefreshTokenRepository r=mock(RefreshTokenRepository.class);RefreshTokenJpaEntity saved=new RefreshTokenJpaEntity(1L,"old");when(r.findByUserId(1L)).thenReturn(Optional.of(saved));TokenPair pair=new TokenService(new JwtTokenProvider(p),r).issue(1L,"user","ADMIN");assertThat(saved.getRefreshToken()).isEqualTo(pair.refreshToken());verify(r,never()).save(any());} }
